      "i": 2,
      "speaker": "bot",
      "text": "अगर आपको कोई नया product खरीदना है या किसी और चीज की enquiry करनी है तो बताइए मैं आपकी मदद कर सकती हूं।"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "पूरे details में पूछने की जरूरत नहीं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "अगर आपको कोई दूसरा product या service चाहिए तो बताइए मैं उसी में help कर सकती हूं।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "Otherwise आप अपनी future needs के लिए IndiaMART की website भी देख सकते हैं।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "नहीं मुझे तो वही होना चाहिए।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको कौन सा product चाहिए था?"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "Please नाम बता दीजिए जिससे मैं आपकी enquiry आगे बढ़ा सकूं।"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "पूरा details."
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "माफ़ कीजिए आपका product नाम clear नहीं हुआ।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "कृपया एक बार साफ़-साफ़ product या service का नाम बता दीजिए।"
    }
  ]
